// Full strings take precedence. Fragments handle journal/history prose composed
// by the shared engine. A single pass avoids translating inserted text again.
const escape = text => text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const keys = Object.keys(translations).sort((a, b) => b.length - a.length);
const fragments = new RegExp(keys.map(key => {
  const start = /^\p{L}/u.test(key) ? '(?<![\\p{L}\\p{N}_])' : '';
  const end = /\p{L}$/u.test(key) ? '(?![\\p{L}\\p{N}_])' : '';
  return start + escape(key) + end;
}).join('|'), 'gu');
export function translateText(value) {
  const text = String(value);
  return Object.hasOwn(translations, text) ? translations[text]
    : text.replace(fragments, fragment => translations[fragment]);
}
